"""Check IDs, names, controls and API files against the supplied source ZIP.

Usage: python test/verify_effect_contract.py path/to/WLED-16.0.1.zip
"""
# AI: below section was generated by an AI
from pathlib import Path
import re
import sys
import zipfile

project = Path(__file__).resolve().parents[1]
with zipfile.ZipFile(sys.argv[1]) as archive:
    prefix = next(n[:-len('wled00/FX.cpp')] for n in archive.namelist() if n.endswith('/wled00/FX.cpp'))
    old = archive.read(prefix+'wled00/FX.cpp').decode('utf-8-sig')
    new = (project/'wled00/FX.cpp').read_text(encoding='utf-8')
    patterns = [r'static const char (_data_\w+)\[\] PROGMEM = ("(?:\\.|[^"\\])*");',
                r'addEffect\((FX_MODE_\w+),\s*&?(\w+),\s*(_data_\w+)\)']
    for pattern in patterns:
        assert re.findall(pattern, old) == re.findall(pattern, new), 'Effect metadata or registration changed'
    pattern = r'^#define\s+(FX_MODE_\w+)\s+([^\n]+)'
    assert re.findall(pattern, archive.read(prefix+'wled00/FX.h').decode(), re.M) == re.findall(pattern, (project/'wled00/FX.h').read_text(), re.M), 'Effect IDs changed'
    for name in ('json.cpp', 'xml.cpp', 'set.cpp', 'const.h'):
        assert archive.read(prefix+'wled00/'+name) == (project/'wled00'/name).read_bytes(), name+' changed'
    assert archive.read(prefix+'platformio.ini') == (project/'platformio.ini').read_bytes(), 'Build profiles changed'
print('Effect IDs, names, controls, registration, API source and build profiles match the supplied ZIP')
# AI: end
